    [6442] = {
        {
            id = 14591,
            score = 7,
            author = "8346",
            text = "You will find these Naga at the Zoram Strand in Ashenvale. They are between the levels of 17-20. If you are a Hunter, stop by this area and tame one of the crabs to get Claw Rank 3.\n\nThese nagas will always drop the Wrathtail Heads if you have the quest, so it is a very simple one to do. You will also find the quest \"Vorsa the Lasher\" http://www.wowhead.com/?quest=6641 here.\n\nIf you are horde, make sure to get the Flight Path at the Zoram Strand!",
            date = "2006-12-13T02:23:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=6442#comments:id=14591",
        },
        {
            id = 346414,
