        {
            id = 1818844,
            score = 6,
            author = "Vestlan",
            text = "Make a simple macro by using the option from the game Menu, or /m in the chat box. The macro should read:\n\n/tar Ashenvale Outrunner\n\nPut it on your bar, any spare space will do, and run around the treeline across from Splintertree Post spamming your new macro. Had the quest done in about two minutes, usually just running to the next Outrunner.\n\nGood Luck.",
            date = "2013-02-27T11:36:56-06:00",
