        },
    },
    [6544] = {
        {
            id = 16954,
            score = 41,
            author = "munix",
            text = "I found this quest to be a lot easier if you clear out the path to the silverwing hold and the little house as well before you start the quest. He will run directly in to the house and not have to fight his way in. When you get in the house he'll walk around for a second and then 4 mobs will come in. Healers can heal the NPCs and just let them fight. Keep Torek alive or you fail the quest. If you die and Torek is still up, don't release until he has killed the mobs, you should still get credit for the quest.",
            date = "2006-12-18T14:44:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=6544#comments:id=16954",
        },
        {
            id = 371836,
            score = 17,
            author = "Corgyll",
            text = "I have a theory about this quest.\nNeed to do some more testing on other chars though, but i think Duriel Moonfire spawns when Torek and his crew kills the nightelf out on that last 'balcony' or what you can call it.\n\nTry letting Torek run in first and aggro the last nightelf on said balcony and see if it works better.\nThough it's just a little theory on my part.",
            date = "2008-09-08T14:19:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=6544#comments:id=371836",
        },
        {
            id = 185058,
            score = 12,
            author = "10013",
            text = "This guy doesn't stop to help if you attack mobs first, so just stand back and let him run in, if it's not clear.",
            date = "2007-11-15T11:47:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=6544#comments:id=185058",
        },
        {
            id = 1193767,
            score = 11,
            author = "Gakknor",
            text = "I can confirm that Torek - [npc=12858 domain=www] is still in the game as of Patch 4.0.3a. If he is not where he is supposed to be that only means that someone has recently started or finished the quest and just like any other escort quest you must wait for him to respawn.",
            date = "2010-11-28T15:39:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=6544#comments:id=1193767",
        },
        {
            id = 177166,
            score = 8,
            author = "bookworm13",
            text = "I'm not sure why so many previous comments were downrated.  This quest is commonly bugged and hasn't been permanently fixed as of 2.2.3.   It is useful information for players to know to contact a GM when it is bugged, and that it can only be fixed during maintenance.  Common bugs are Duriel Moonfire and her escort not appearing after the outpost has been cleared and also Torek's escort not respawning after a failed attempt (though that is not really quest breaking).\n\nYou should also know that Torek does not regen health when out of combat, and bandaging him does not work.  You can only heal him if you have a healing class in your group.  If you are going to solo the quest then the above tips about clearing the area beforehand are a great help.",
            date = "2007-10-31T06:15:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=6544#comments:id=177166",
        },
    },
