    [13595] = {
        {
            id = 1182669,
            score = 119,
            author = "239616",
            text = "32,23 for the bottle.",
            date = "2010-11-24T18:57:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13595#comments:id=1182669",
        },
        {
            id = 3173614,
            score = 24,
            author = "amymicaela",
            text = "So you will need to acquire a \"Bottle of Wildfire\" to do the quest. Which is near the quest, NOT the quest giver.\nThe \"Bottle of Wildfire\" is very near to Bathran's Corpse. If you are looking at the corpse, turn and look to the right and you will see a white tent and a table next to that, the bottle is on that table.\nCoordinates of bottle: 32/23",
            date = "2019-11-25T18:17:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13595#comments:id=3173614",
        },
        {
            id = 1525313,
            score = 12,
            author = "717646",
            text = "Known random quotes from Horde mobs (that I saw. Not sure if they only say these if you have the quest);\n\nForsaken Herbalist says: Someone! Help!\nForsaken Herbalist says: Some nice contagion of rot for you, my pretty?\nForsaken Herbalist says: You will not stop us, filthy !\n\nOrc Overseer says: Back to work you lazy dead cur!\nOrc Overseer says: Warchief Hellscream will have your head if you don't pick up the pace, Forsaken!\nOrc Overseer says: They say there's no rest for the wicked. That means you!\nOrc Overseer says: I could use some more blood ale to quench my thirst!\nOrc Overseer says: A potion to melt the elves? Maybe you'll need it, Forsaken. I have my mace to crush their skulls!\n\nAny overseer will say the last two when you're near the potion (especially the last one). Wanted to add that in. Use that as a queue to know where to go.",
            date = "2011-09-23T02:52:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13595#comments:id=1525313",
        },
        {
            id = 1223767,
            score = 9,
            author = "493620",
            text = "Table is farther away than I first thought. It is over the wall by the orc encampment and the table is at 32,23. You will have to kill two mobs than loot the bottle off of the table. Quest is easy after getting the bottle.",
            date = "2010-12-11T05:05:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13595#comments:id=1223767",
        },
        {
            id = 1300603,
            score = 5,
            author = "Allya",
            text = "You want to target Bathran's Corpse (about 33, 21)(to the left of the table [as you face North] with the Potion of Wildfire), not the Ancient Bathran.  The corpse is surrounded by Orc's so be careful.",
            date = "2011-01-19T14:23:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13595#comments:id=1300603",
        },
    },
    [13602] = {
        {
            id = 5276571,
            score = 4,
            author = "llollz",
            text = "Just came here to mention that if you're having an issue with the phasing in 9.1.5, you probably need to complete the https://www.wowhead.com/quest=53847 quest line first.",
            date = "2021-11-06T18:58:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13602#comments:id=5276571",
        },
        {
            id = 2587364,
            score = 3,
            author = "neurocase",
            text = "Currently on 8.0, this and https://www.wowhead.com/quest=26465 are difficult (if not near impossible) to complete, thanks to The Zoram Strand phasing oddly due to its proximity with southern Darkshore. Speaking with https://www.wowhead.com/npc=141489 doesn't currently fix this either, at the moment (2/8/18) as she doesn't appear to be phasing the zone correctly, which is having this ripple effect on the Zoram Strand. The best you can do is tag or taunt any naga that wander close enough to the very edge of the quest's marked borders, while you're still flagged as being in Ashenvale. Flying to Ruuzel's Isle (7, 14) also yields several naga, but sadly, no statuettes for https://www.wowhead.com/quest=26465 Hopefully, this phasing issue (and Zidormi, by extension) will be fixed when the expansion launches fully on the 14th.",
            date = "2018-08-02T23:45:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13602#comments:id=2587364",
        },
    },
    [13612] = {
        {
            id = 1076408,
            score = 7,
            author = "447186",
            text = "New quest for Cataclysm. Given by a quest giver called Kadrak(loc 42,15) located near the watchtowers on the border of Northern barrens and Ashenvale.\n\nJust pass through the gate into Ashenvale. These hostile Nightelves are all over the place, you can't miss them.\n\nLance\nBeta tester for;\nWrath of the Litch King\nCataclysm",
            date = "2010-07-08T23:54:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13612#comments:id=1076408",
        },
        {
            id = 1197910,
            score = 7,
            author = "714203",
            text = "Easily found on both sides of the road at [69,84] you can't miss them\nWowhead Map (http://www.wowhead.com/maps?data=331:690840)\n\nRecomend doing this with:\nRescue the Fallen (http://www.wowhead.com/quest=13613)\nEmpty Quivers (http://www.wowhead.com/quest=13615)",
            date = "2010-11-30T13:21:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13612#comments:id=1197910",
        },
        {
            id = 1478034,
            score = 2,
            author = "witteafval",
            text = "He talks of keeping the enemy \"on their heels\" when you turn in the quest. I wonder if he really meant \"on their toes.\"",
            date = "2011-07-24T02:17:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13612#comments:id=1478034",
        },
        {
            id = 3197155,
            score = 1,
            author = "Wyr3d",
            text = "There are two breadcrumbs for this quest. The first (https://www.wowhead.com/quest=28876/to-the-morshan-rampart) is a lead in from Azshara so if you ran that zone, you'll be on this quest, and if you ran Northern Barrens, you don't really need to worry about it. it awards a little XP and a tiny amount of Orgrimmar rep.\n\nThe second (https://www.wowhead.com/quest=28493/warchiefs-command-ashenvale) is from the warboards so don't worry about that either. Chances are it won't be available by the time you get to this point, coz you will have out-leveled the pickup limits. Still don't need to worry over it, this the main questline from Northern Barrens takes you here anyway. This awards the same rep and XP as the first one, and a little silver.",
            date = "2020-03-31T09:53:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13612#comments:id=3197155",
        },
        {
            id = 2622881,
            score = -3,
            author = "1930122",
            text = "See the Mor'shan Defence re any attacks:  Max  - youtu.be/f_AkY3hrflQ\na-t- morshan-net-au",
            date = "2018-10-12T00:21:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13612#comments:id=2622881",
        },
    },
    [13613] = {
        {
            id = 1076375,
            score = 9,
            author = "447186",
            text = "New quest for Cataclysm. Given by a quest giver called Dinah Halfmoon (loc 42,15) located near the watchtowers on the border of Northern Barrens and Ashenvale.\n\nYou are given a medicated salve that you will have to apply to the wounded Mor'shan defenders. They are all over the place amongst the hostile Nightelf attackers. You will see them all as you pass through the gate into Ashenvale.\n\nLance\nBeta tester for;\nWrath of the Litch King\nCataclysm",
            date = "2010-07-08T22:54:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13613#comments:id=1076375",
        },
        {
            id = 1558168,
            score = 6,
            author = "406368",
            text = "Slightly misleading above about their location, but not too badly. The WOUNDED Mar'shan Defenders can be found after exiting the gate and going into the treeline where the Dark Elf attackers are shooting arrows from. They are in a kneeling position.\n\nNOTE for Hunters: If you are using Track Humanoids, DO NOT be fooled by the dead Mar'shan Defenders that are inside of the camp itself. This is a modeling error that hasn't been corrected since 4.0.3. The true quest NPC's are OUTSIDE of the barrier north into Ashenvale (not south into Barrens).",
            date = "2011-10-31T01:48:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13613#comments:id=1558168",
        },
    },
    [13615] = {
        {
            id = 1076373,
            score = 9,
            author = "447186",
            text = "New quest for Cataclysm. Given by a quest giver called Truum(loc 42,15) located near the watchtowers on the border of Northern barrens and Ashenvale.\n\nJust pass through the gate into Ashenvale. These are sticking out of the ground all amongst the Nightelf attackers and the wounded Mor'shan defenders. I found a good concentration of them at 69,85. You will have to fight off many hostile Nightelves, so you might as well do \"Mor'shan Defense\" aswell.\n\nLance\nBeta tester for;\nWrath of the Litch King\nCataclysm",
            date = "2010-07-08T22:51:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13615#comments:id=1076373",
        },
        {
            id = 1188859,
            score = 7,
            author = "466912",
            text = "Note that these arrows are extremely hard to see.",
            date = "2010-11-26T21:05:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13615#comments:id=1188859",
        },
        {
            id = 1193464,
            score = 7,
            author = "643706",
            text = "The best thing to do, I found, is to look for the little glow lights that come up - otherwise it's next to impossible to locate these. (I've also uploaded a screenshot)",
            date = "2010-11-28T13:29:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13615#comments:id=1193464",
        },
        {
            id = 1351031,
            score = 7,
            author = "670789",
            text = "They are a lot easier to find if you turn your Particle Density setting up (Interface > Video > Particle Density dropbox in the lower right). Having this setting down can make things a lot more difficult for most quests like this.",
            date = "2011-02-26T16:12:53-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13615#comments:id=1351031",
        },
        {
            id = 1260346,
            score = 3,
            author = "746070",
            text = "As i was doing the quest, i noticed that they usually are near the wounded Mor'shan defenders. The q item is really not that visible, so looking for them around the wounded guys may help.",
            date = "2010-12-26T16:34:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13615#comments:id=1260346",
        },
    },
