        {
            id = 1212799,
            score = 8,
            author = "165655",
            text = "Fairly straightforward quest, you need to walk around on the battlefield with the three sentinels you are given and take out 10 of the Horde invaders and three of the big machines.  Make sure you don't draw aggro from more than two or three invaders at the same time, and try to take out nearby invaders before you go for the wreckers.  You should easily kill more than 10 invaders taking out three of the machines.",
            date = "2010-12-07T18:08:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13624#comments:id=1212799",
