    [13640] = {
        {
            id = 1076432,
            score = 18,
            author = "447186",
            text = "When you have finished talking to Gorka find yourself a Demoralized Peon to talk to. If they agree to chop wood for you follow them and stick close by. They will be attacked by Ashenvale Stalkers (Nightelves). Your job is to kill them before they kill your poor frightened peons. If you are successfull your peon will provide you with a bundle of \"Freshly Cut Wood\". It will be lying on the ground next to your peon. Your peon will then despawn and you will have to find another one to do it all over again.\n\nWhen you have your five bundles of wood, hand the quest in to Gorka.\n\nLance\nBeta tester for;\nWrath of the Litch King\nCataclysm",
            date = "2010-07-09T00:47:14-05:00",
