    [13841] = {
        {
            id = 1448143,
            score = 61,
            author = "174832",
            text = "On my Lock:\n\nFools!\n\nThis Draaka woman has allowed herself to be manipulated by a demon!\n\nAnd I smell its taint on you as well, warlock....\n\nReally Garrosh?  You sense demon taint on a warlock.  Nothing escapes you does it.",
            date = "2011-06-22T16:41:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13841#comments:id=1448143",
        },
        {
            id = 1255856,
            score = 34,
            author = "287990",
            text = "To be able to start this quest, you must first complete all of the Mor'shan Front quests which lead you to the Warsong Lumber Camp quests which you must also complete, which take you to Splintertree Post.\n\nThe chain quest that Draaka/Durak gives you is the one that allows you to take this quest.",
            date = "2010-12-24T00:39:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13841#comments:id=1255856",
