    [13876] = {
        {
            id = 1206894,
            score = 37,
            author = "718591",
            text = "Location 41.6, 35.7\n\nEnter the cave, take the first path to the left, he is on an island.  Level 24 with 1302 health.",
            date = "2010-12-04T20:52:42-06:00",
