        },
        {
            id = 1393669,
            score = 6,
            author = "Gasparus",
            text = "I had the exact opposite happen.  Killed him five times with Sky Lightning with no DOT on him.  Then I tried letting the DOT kill him and got credit.  If it's bugged for you, might want to try it both ways.",
            date = "2011-04-17T16:47:32-05:00",
