        },
        {
            id = 1193246,
            score = 5,
            author = "622488",
            text = "Very easy quest.  After accepting the quest, talk to the vortex again and he will turn you into a cyclone and swap out your skill bar.  You will automatically fly up to the boss and, after defeating him, will be automatically flown back down.  In battle, throw the DoT spell on him (#2) and then hit on refresh, optherwise spamming the tiny damage spell (#1).  Damage text will scroll when you have the Lordly  Immolation on you and just immediately cleanse it with #3.  As long as you keep it cleansed (comes every 15 seconds or so) you will have no problems.",
            date = "2010-11-28T11:55:53-06:00",
