            author = "1028336",
            text = "First tried using both Sky Lightning and Vortex Vengence: No kill credit.\nNext tried using only Sky Lightning as final kill strike, no DoT: No kill credit.\nTried using only Sky Lightning throughout the fight: no kill credit.\nFinally tried using only Vortex Vengence throughout the fight: Kill Credit! Yay!",
            date = "2012-09-03T12:57:53-05:00",
