    [13890] = {
        {
            id = 1076812,
            score = 110,
            author = "447186",
            text = "For this quest you will need to kill 10 Mystlash Hydra (http://cata.wowhead.com/npc=3721#comments). They will drop Mystlash Hydra Blubber. You will find a lot of them in the waters to the west of Zoram'gar Outpost starting about 9,33. When you have your 10 go back to the forge (11,35). It's inside the building. Melt your blubber into oil at the forge and make your way over to the lighthouse at  (6,28). Climb the stairs to the top, use your oil on the Lighthouse Fire and your done.\n\nLance\nBeta tester for;\nWrath of the Litch King\nCataclysm",
            date = "2010-07-09T16:07:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13890#comments:id=1076812",
        },
        {
            id = 2602390,
            score = 34,
            author = "1765217",
            text = "You're here because you ran straight to the lighthouse like a mindless peon, caring to read the quest description only in front of that fire that you clicked ten times in vain. How do I know? I did exactly the same thing.\n\nSo, here's what you need to know: Mystlash Hydra Oil (https://www.wowhead.com/item=46366/mystlash-hydra-oil) is created by combining 10 https://www.wowhead.com/item=46365, that are dropped by Mystlash Hydras (https://www.wowhead.com/npc=3721/mystlash-hydra). You can find them approximately where you have to pick up the scrap metal for https://www.wowhead.com/quest=13883.\n\nJust head there, pick up the blubbers,go back to the forge to melt the oil and finally you can go back to the lighthouse to lit the fire.",
            date = "2018-08-23T12:59:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13890#comments:id=2602390",
        },
        {
            id = 1612721,
