    [13958] = {
        {
            id = 1969770,
            score = 2,
            author = "1077781",
            text = "FYI- dont try to run up the front ramp! Ally guards are pvpd. If you are looking at the ramp, take the path to the left and go up behind raynewood. Thagg is up behind the tower.",
            date = "2014-06-02T21:45:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13958#comments:id=1969770",
        },
        {
            id = 2471175,
            score = 1,
            author = "swedengamer",
            text = "Did this quest as of patch 7.1.5. Keep an eye out for Shadumbra, a cat that prowls the area. This cat drops a quest with some nixe xp rewards.\n\nThis cat is one of several creatuers in Ashenvale that drops an item that leads to a quest. It used to be part of the old classic quest, The Ashenvale Hunt, but no more. Also there was an NPC that offered tips on where to locate these beasts, but no more. The NPC still exist, Senani Thunderheart, a female tauren, but she doesn't offer any tips anymore. She has also been moved from Splintertree Post to Silverwind Refuge during the remake of this zone for Cataclysm. But you can still do these quests, but not the followup that existed once you did all of these back in the days.\n\nThe other creatures that drop are as following:\n\nUrsangous - you will most likely run into this bear during the two quests They're Out there! and Building Your Own Coffin.\n\nTideress - part of the quest Simmer Down Now.\n\nSharptalon - a bird that you will most likely run into during the quest Rotting Slimes during the beginning quests of this zone.",
            date = "2017-02-10T04:44:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13958#comments:id=2471175",
        },
    },
