    [13979] = {
        {
            id = 1646149,
            score = 18,
            author = "713717",
            text = "FYI: this is a single quest - no chain required.  The target isn't even an elite (1398 HP).  So basically, at level 23, come get a free blue item.\n\nSploder stands on a little balcony on the front of the bomb tower.  Access by walking up the track / ramp in the back of the tower.  He's standing in front of a backlit window, dual wielding torches.\n\nIf you're twinking 24, the ring is temporarily good for rogues, hunters & feral druids while you're grinding for your monkey or agility https://www.wowhead.com/item=9461 in Gnomer (which will be an upgrade but may take a long, long time to get).\n\nHorde side has a marginally better ring: https://www.wowhead.com/item=65725",
            date = "2012-03-29T10:02:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13979#comments:id=1646149",
        },
        {
            id = 1302228,
            score = 2,
            author = "278023",
            text = "If you approach from the S as I did, you will need to go around to the N side of the tower the bomb is on and climb up the tracks or whatever they are to kill the technician and the approach Sploder on up the track.\n\nHe is on the S side and not a difficult kill and you get his head.\n\nDo not forget the quest from the bomb after killing Sploder. I had to go around to the N side and farthert uo killing one more technician on the way.",
            date = "2011-01-20T19:25:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13979#comments:id=1302228",
        },
        {
            id = 1635201,
