            text = "Don't forget to combine this with Ze Gnomecorder as the technicians there all have the drop needed and very easy to kill.",
            date = "2012-03-04T21:17:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13979#comments:id=1635201",
        },
    },
