    [26449] = {
        {
            id = 1188191,
            score = 33,
            author = "311745",
            text = "Diathorus the Seeker is at 78.47, 83.88. Inside den at top of Demon Fall Ridge, across first bridge. (He is level 22)\nGorgannon is at 89.74, 76.70. At the end of Demon Fall Canyon (He is also level 22) Melee swings + Knockdown effect, and a Shadowbolt that can be interrupted.",
            date = "2010-11-26T16:17:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26449#comments:id=1188191",
        },
        {
            id = 1228573,
            score = 24,
            author = "463938",
            text = "Additional detail on finding Diathorus: turn right as you enter Demonfall Canyon and continue to the western end, where Grom Hellscream's grave is.  The path up to the den starts just a few paces north of Grom's grave, and it's marked by glowing red stones.  Go all the way up the path, cross the flat open area to the den, enter the den and go down the tunnel; you'll find Diathorus standing behind an infernal.",
            date = "2010-12-12T19:10:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26449#comments:id=1228573",
        },
        {
            id = 2356619,
            score = 23,
            author = "NessieMo",
            text = "First kill https://www.wowhead.com/npc=17300 for https://www.wowhead.com/item=45477 then find the Barrow Den with https://www.wowhead.com/npc=6072 for https://www.wowhead.com/item=45476.\n\nLocations aren't immediately obvious, especially for the Barrow Den, so coordinates formatted for TomTom / Paste users are below:\n\n/way Ashenvale 84.17 71.78 #1 Start of track up Felfire Hill to Gorgannon\n/way Ashenvale 89.66 76.74 #2 Kill Gorgannon for his Flaming Blade\n/way Ashenvale 83.04 78.06 #3 Start of path to Barrow Den follow these shiny posts up\n/way Ashenvale 78.38 81.84 #4 Entrance to Barrow Den\n/way Ashenvale 78.46 83.89 #5 Diathorus the Seeker over bridge in Barrow Den",
            date = "2016-07-25T04:30:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26449#comments:id=2356619",
        },
        {
            id = 1280070,
            score = 17,
            author = "dustbunny45",
            text = "Go down the winding entrance, once you come to the opening of the lair, look at the chamber directly across from you at the end of the center bridge.  You'll see a Searing Infernal inside the cubby with Diathorus standing behind him.  If you look carefull you can just see the tops of his big blue wings.  I missed seeing him in there a few times due to the large Infernal in front of him.  There seems to be some debate that he spawns in different spots in the maze, but most seem to be finding him in the den just across the bridge. Happy hunting.",
            date = "2011-01-06T07:56:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26449#comments:id=1280070",
        },
        {
            id = 1608809,
            score = 11,
            author = "933764",
            text = "I had a bit of trouble with this so hopefully this will help a bit.\n\nEnter Demon fall Canyon and kill demons as you go. You will eventually hit a fork in the road.\nGo straight to get the Seeker Fel Spear.\nYou will enter a clearing and on your right you will see an orange light. follow the orange lights up the hill. This will lead you to another clearing.\nAt the back of this clearing enter the thing that looks like a house and follow the tunnels down. When it opens up go straight across the bridge and kill Diathorus the seer for the seekers fel spear.\n\nNow make your way back to the fork in the road and take the other path.\n\nKill the demons as you make your way up the path.\nYou will reach another fork in the road. It doesn't matter which one you choose since they both meet at the same spot. Work your way to the back of the clearing and you will find Gorgannon. He has a sucubus next to him that you will pull as well so keep that in mind.\n\nAldo for anyone killing critters there a few in here as well..\n\nHappy Questing!",
            date = "2012-01-08T16:35:04-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26449#comments:id=1608809",
        },
    },
